// SessionStatus What happened to a session as data, independent of the wall clock.
// `moved` means the room changed; `delayed` means the times were shifted.
type SessionStatus string

// SessionView One materialised session as the board and the map show it.
//
// **Room semantics.** `roomId` / `roomCode` / `floor` always describe the **effective**
// room — where the session actually happens. For a session with `status = moved`,
// `movedFromRoomCode` holds the original room; the board keeps the row in the original
// room's column and renders a `MOVED → {roomCode}` pill, while the map colours the new room.
//
// **Time semantics.** `startAt` / `endAt` are absolute UTC instants that already include
// any delay (`status = delayed`, `delayMinutes` says by how much). Clients must not
// re-apply the delay.
//
// **Identity.** `sessionId` is `"{lessonId}:{date}"` for a templated session and
// `"x:{overrideId}"` for an `extra` one; `lessonId` is absent for `extra` sessions.
type SessionView struct {
	// Conflict True when another session overlaps the same room; the earlier start owns the room.
	Conflict    bool   `json:"conflict"`
	CourseCode  string `json:"courseCode"`
	CourseTitle string `json:"courseTitle"`

	// DelayMinutes Minutes the session was pushed back when `status = delayed`.
	DelayMinutes *int32 `json:"delayMinutes,omitempty"`

	// EndAt Absolute end, delay already applied.
	EndAt time.Time `json:"endAt"`

	// Floor Floor of the effective room.
	Floor int32 `json:"floor"`

	// Groups Student group codes attending, in display order.
	Groups []string `json:"groups"`

	// LessonId The lesson template this session comes from. Absent for `extra` sessions.
	LessonId *openapi_types.UUID `json:"lessonId,omitempty"`

	// LessonType Pedagogical form of a session.
	LessonType LessonType `json:"lessonType"`

	// MovedFromRoomCode Original room code when `status = moved`.
	MovedFromRoomCode *string `json:"movedFromRoomCode,omitempty"`

	// Note Free-text note attached by the override that changed this session.
	Note *string `json:"note,omitempty"`

	// Phase Where a session sits relative to "now", computed by the Go engine:
	// `upcoming` → `soon` (within `SOON_WINDOW`, default 10 min) → `live` →
	// `ending` (last `ENDING_WINDOW`, default 5 min) → `done`.
	// A cancelled session is always `cancelled` and never occupies its room.
	Phase Phase `json:"phase"`

	// RoomCode Effective room code (after a move).
	RoomCode string `json:"roomCode"`

	// RoomId Effective room id (after a move).
	RoomId openapi_types.UUID `json:"roomId"`

	// SessionId `"{lessonId}:{date}"`, or `"x:{overrideId}"` for an extra session.
	SessionId string `json:"sessionId"`

	// StartAt Absolute start, delay already applied.
	StartAt time.Time `json:"startAt"`

	// Status What happened to a session as data, independent of the wall clock.
	// `moved` means the room changed; `delayed` means the times were shifted.
	Status SessionStatus `json:"status"`

	// Teacher Compact teacher reference embedded in session views.
	Teacher TeacherRef `json:"teacher"`
}

// Severity Visual weight of a ticker announcement.
type Severity string

// SlotInfo One numbered lesson slot. `startsAt` / `endsAt` are **local** wall-clock times
// `HH:MM`, not instants — the engine resolves them through `Building.timezone`.
type SlotInfo struct {
	EndsAt string             `json:"endsAt"`
	Id     openapi_types.UUID `json:"id"`

	// Idx 1-based index within the building; this is the admin API's `slotIdx`.
	Idx      int32  `json:"idx"`
	StartsAt string `json:"startsAt"`
}

// SlotList The building's lesson slots, ordered by `idx`.
type SlotList struct {
	Slots []SlotInfo `json:"slots"`
}

// Snapshot The complete board state at `at`. Sent as the body of `getBoard` and as the payload of
// the SSE `snapshot` event — always a full state, never a delta, so a dropped message
// costs nothing.
type Snapshot struct {
	// At The instant this snapshot describes.
	At       time.Time `json:"at"`
	Building string    `json:"building"`

	// Date Local building date of `at`. Shown in the header.
	Date string `json:"date"`

	// Next Sessions in phase `soon` or `upcoming` starting within the 90-minute horizon (cancelled and moved ones included), sorted by `startAt`.
	Next []SessionView `json:"next"`

	// NextTransitionAt The earliest instant after `at` at which any session crosses a phase boundary.
	// The scheduler sleeps until then (capped at 5 minutes). Nullable: `null` when nothing
	// is left to happen today.
	NextTransitionAt *time.Time `json:"nextTransitionAt,omitempty"`

	// Now Sessions in phase `live` or `ending`, sorted by `endAt`.
	Now []SessionView `json:"now"`

	// Rooms Live state of every room of the building, schedulable or not.
	Rooms []RoomLiveState `json:"rooms"`

	// Stats Header and legend counters.
	Stats Stats `json:"stats"`

	// WeekNumber 1-based teaching week counted from `semester.starts_on`.
	WeekNumber int32 `json:"weekNumber"`

	// WeekParity Parity of the current teaching week, counted from `semester.starts_on`.
	WeekParity WeekParity `json:"weekParity"`
}

// Stats Header and legend counters.
type Stats struct {
	// RoomsBusy Schedulable rooms whose phase is `live` or `ending`.
	RoomsBusy int32 `json:"roomsBusy"`

	// RoomsTotal Number of schedulable rooms in the building.
	RoomsTotal    int32 `json:"roomsTotal"`
	SessionsDone  int32 `json:"sessionsDone"`
	SessionsToday int32 `json:"sessionsToday"`
}

